// Virtual scrolling: render only visible rows (100 visible out of 100,000)
@Component({
  imports: [ScrollingModule],
  template: \`
    <cdk-virtual-scroll-viewport itemSize="48" style="height: 500px">
      @for (item of items(); track item.id) {
        <div *cdkVirtualFor="let item of items(); trackBy: trackById" class="row">
          {{ item.name }}
        </div>
      }
    </cdk-virtual-scroll-viewport>
  \`
})
export class BigListComponent {
  items = signal<Item[]>([]);
  trackById = (i: number, item: Item) => item.id;
}

// Pure pipe: compute display values without impure side effects
@Pipe({ name: 'relativeTime', pure: true, standalone: true })
export class RelativeTimePipe implements PipeTransform {
  transform(date: Date): string {
    const diff = Date.now() - date.getTime();
    if (diff < 60000) return 'just now';
    if (diff < 3600000) return Math.floor(diff / 60000) + 'm ago';
    return Math.floor(diff / 3600000) + 'h ago';
  }
}

// NgOptimizedImage: automatic lazy loading, srcset, LCP priority
@Component({
  imports: [NgOptimizedImage],
  template: \`
    <img [ngSrc]="user.avatarUrl" width="64" height="64" [priority]="isAboveFold">
  \`
})
export class AvatarComponent {
  @Input() user!: User;
  @Input() isAboveFold = false;
}
